message.content:
[
  {
    "sys_consequence_reasoning": "right call, five against one",
    "pd_harm_distress": "my hands haven't stopped shaking",
    "pda_practical_counterfactual": "If whoever assigns the crews had kept that man off the spur"
  },
  {
    "sys_consequence_reasoning": "Five people are alive",
    "pd_harm_distress": "sick feeling in my stomach won't go",
    "pda_responsibility": "because I sent the train there",
    "pda_harm_regret": "regret that more than I can say",
    "pda_practical_counterfactual": "should have radioed both crews to clear the line"
  },
  {
    "pd_decision_conflict": "Doing nothing would have been terrible too",
    "pda_responsibility": "pulling it made his death mine",
    "pd_harm_distress": "My chest goes tight",
    "pda_harm_regret": "I'd give a lot to undo that part",
    "pda_practical_counterfactual": "If I'd walked the side track at the start of shift"
  },
  {
    "pd_harm_distress": "my stomach turns over",
    "pda_harm_regret": "I'm sorry it was his life I traded",
    "pda_practical_counterfactual": "foreman should never have split the crew"
  },
  {
    "pd_decision_conflict": "least bad option",
    "pd_harm_distress": "I feel cold and a bit dizzy",
    "pda_harm_regret": "regret what my choice did to him",
    "pda_practical_counterfactual": "working warning horn on that section might have given him time"
  },
  {
    "pda_responsibility": "he died because of what I did",
    "pda_harm_regret": "hate that he died because of what I did",
    "pda_practical_counterfactual": "If maintenance had kept the train's brakes sorted",
    "pd_harm_distress": "mostly for this knot in my gut to loosen"
  },
  {
    "sys_consequence_reasoning": "Five families get their people back tonight",
    "pda_responsibility": "His doesn't, because of me",
    "pd_harm_distress": "makes my throat close up",
    "pda_harm_regret": "sorry, deeply, that he paid for it",
    "pda_practical_counterfactual": "company should have installed a derail"
  },
  {
    "pd_decision_conflict": "felt right in the moment and it feels awful now",
    "pd_harm_distress": "My knees are still weak",
    "pda_practical_counterfactual": "If he'd had one, he could have been warned off",
    "pda_harm_regret": "regret costing him his life",
    "pd_personal_consequence_anxiety": "don't know what happens to me next, and that frightens me"
  },
  {
    "sys_consequence_reasoning": "saved more people",
    "pda_responsibility": "actively killed a man",
    "pd_harm_distress": "feel sick, like I might actually throw up",
    "pda_harm_regret": "I'd take it back if I could",
    "pda_practical_counterfactual": "scheduling office hadn't sent crews onto both tracks"
  },
  {
    "pd_harm_distress": "My heart's still pounding",
    "pda_harm_regret": "that man's death sits on me and I regret it badly",
    "pda_practical_counterfactual": "should have pushed harder for the lockout rule",
    "pda_responsibility": "I raised it once and let it drop"
  }
]
